function safeParseJson(jsonString, fallbackValue = {}) {
  try {
    // Code that might throw a SyntaxError
    const parsedData = JSON.parse(jsonString);
    return parsedData;
  } catch (error) {
    // Catches and handles the runtime exception
    console.warn(`JSON Parse failed: ${error.message}. Returning fallback.`);
    return fallbackValue;
  } finally {
    // ALWAYS runs regardless of whether an exception occurred or return statement executed
    console.log("Parse operation attempted.");
  }
}

console.log(safeParseJson('{"status": "ok"}')); // { status: 'ok' }
console.log(safeParseJson('bad json text'));     // {}

class ValidationError extends Error {
  constructor(message, fieldName, statusCode = 400) {
    super(message);
    this.name = "ValidationError";
    this.fieldName = fieldName;
    this.statusCode = statusCode;

    // Captures proper stack trace in V8 engines
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, ValidationError);
    }
  }
}

function validateUserAge(age) {
  if (typeof age !== "number" || age < 18) {
    throw new ValidationError("User must be at least 18 years old.", "age", 422);
  }
  return true;
}

try {
  validateUserAge(15);
} catch (err) {
  if (err instanceof ValidationError) {
    console.error(`[${err.name}] Status ${err.statusCode} on field '${err.fieldName}': ${err.message}`);
  } else {
    console.error("Unexpected error:", err);
  }
}

const users = [
  { id: 1, name: "Alice", role: "Admin", active: true },
  { id: 2, name: "Bob", role: "Editor", active: false },
  { id: 3, name: "Charlie", role: "Viewer", active: true }
];

// 1. console.table formats arrays of objects into structured terminal tables
console.table(users);

// 2. console.time and console.timeEnd measures execution benchmark durations
console.time("Filtering Users");
const activeUsers = users.filter(u => u.active);
console.timeEnd("Filtering Users");

function inspectProcess(item) {
  // 3. The 'debugger' statement pauses script execution and triggers DevTools breakpoint
  if (!item.active) {
    // debugger; // Uncomment when DevTools is open to inspect local scope variables
    console.log("Paused on inactive user:", item.name);
  }
}

users.forEach(inspectProcess);
